"use strict";
// The binding of the island module is written again, so it is not the
// module at every use: this package cannot stay native and runs in the
// island with the package it requires.
var pantry = require("pantry");

if (typeof pantry.find("salt").label !== "string") {
  pantry = {
    find: function () {
      return { label: "none", grams: 0 };
    },
  };
}

exports.label = function label(name) {
  return pantry.find(name).label;
};
